const raw = ($input.item && $input.item.json) ? $input.item.json : {};
const extracted = raw.extracted_params || {};
const projectStyle = raw.project_style || {};
const visualMedium = (raw.visual_medium || projectStyle.visual_medium || projectStyle.visual_style || 'ANIME').toString().toUpperCase().trim();
const customSystemPrompt = (raw.custom_system_prompt || projectStyle.custom_system_prompt || '').toString().trim();
const systemPromptTitle = (raw.system_prompt_title || projectStyle.system_prompt_title || 'Default').toString().trim();

const intent = (raw.intent || raw.downstream_command || 'BIBLE_CHAT').toString().toUpperCase().trim();
const rawText = (raw.rawText || raw.userPrompt || raw.text || '').toString().trim();
const userPrompt = (raw.userPrompt || raw.rawText || '').toString().trim();
const project_id = raw.project_id || null;
const project_name = raw.project_name || 'Active Project';
const current_season = Number(raw.current_season || extracted.season_no || 1);
const sessionId = (raw.sessionId || `sess_${$execution.id}`).toString();

if (!project_id) {
  throw new Error('WF-01 Error: project_id is required to hydrate or mutate Story Bible state.');
}

return {
  json: {
    intent, rawText, userPrompt, project_id, project_name, current_season, sessionId,
    visual_medium: visualMedium,
    system_prompt_title: systemPromptTitle,
    custom_system_prompt: customSystemPrompt,
    project_style: projectStyle,
    baseHash: (raw.baseHash || raw.base_hash || extracted.base_hash || '').toString(),
    baseVersion: Number(raw.baseVersion || raw.base_version || extracted.base_version || 0),
    user_infrastructure: raw.user_infrastructure || {}
  }
};

